findings.codeql_raw_query:
/**
 * @name Zip Slip - Unsafe archive extraction
 * @description Extracting archives without validating paths can lead to path traversal
 * @kind path-problem
 * @problem.severity error
 * @id py/zip-slip
 * @tags security
 *        external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module ZipSlipConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    exists(DataFlow::CallCfgNode call |
      // ZipFile.namelist() or members
      call = API::moduleImport("zipfile").getMember("ZipFile").getReturn().getMember(["namelist", "infolist"]).getACall() and
      source = call
      or
      // TarFile.getmembers() or getnames()
      call = API::moduleImport("tarfile").getMember(["open", "TarFile"]).getReturn().getMember(["getmembers", "getnames"]).getACall() and
      source = call
      or
      // Individual member names from archive
      exists(DataFlow::AttrRead attr |
        attr.getAttributeName() = "filename" or
        attr.getAttributeName() = "name"
      |
        source = attr
      )
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // File operations that could be vulnerable
      call = API::moduleImport("os").getMember("makedirs").getACall() or
      call = API::moduleImport("os").getMember("mkdir").getACall() or
      call = API::builtin("open").getACall()
    |
      sink = call.getArg(0)
    )
    or
    exists(DataFlow::CallCfgNode call |
      // ZipFile.extract or extractall
      call = API::moduleImport("zipfile").getMember("ZipFile").getReturn().getMember(["extract", "extractall"]).getACall()
    |
      sink = call.getArg([0, 1])
    )
  }
}

module ZipSlipFlow = TaintTracking::Global<ZipSlipConfig>;
import ZipSlipFlow::PathGraph

from ZipSlipFlow::PathNode source, ZipSlipFlow::PathNode sink
where ZipSlipFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential zip slip vulnerability from $@.", source.getNode(), "archive member"
